import React from 'react';
import { Calendar, Clock } from 'lucide-react';

const ScheduleTab = () => (
  <div className="w-full h-full bg-white border-[8px] border-[#47510B] rounded-[50px] p-8 shadow-2xl flex flex-col gap-6">
    <h3 className="text-4xl font-[1000] italic text-[#AB1717] uppercase underline decoration-[#CAD23C]">Collection_Log</h3>
    <div className="space-y-4 overflow-y-auto pr-2">
      {[1, 2, 3, 4, 5].map(i => (
        <div key={i} className="flex justify-between p-6 bg-[#FDFAD8] border-4 border-[#47510B] rounded-2xl shadow-[6px_6px_0_0_#47510B]">
          <div className="flex items-center gap-4">
            <Clock className="text-[#AB1717]" />
            <span className="font-black">MAR_2{i}_2026</span>
          </div>
          <span className="font-black text-[#47510B]">STATUS: COMPLETED</span>
        </div>
      ))}
    </div>
  </div>
);

export default ScheduleTab;
